import React, { useState } from 'react';
import { ethers } from 'ethers';
import { AlphaRouter, SwapType } from '@uniswap/smart-order-router';
import { Token, CurrencyAmount, TradeType, Percent } from '@uniswap/sdk-core';
import JSBI from 'jsbi';

const CHAIN_ID = 1;
const ALCHEMY_URL = 'https://eth-mainnet.g.alchemy.com/v2/YOUR_KEY_HERE';

// Your fee wallet
const FEE_RECIPIENT = '0x279C0C2B6eF16d471CD4e5eC525FFDD8Eeae5446';

// Common tokens
const WETH = new Token(CHAIN_ID, '0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2', 18, 'WETH', 'Wrapped Ether');
const USDC = new Token(CHAIN_ID, '0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48', 6, 'USDC', 'USD Coin');
const USDT = new Token(CHAIN_ID, '0xdAC17F958D2ee523a2206206994597C13D831ec7', 6, 'USDT', 'Tether');
const DAI  = new Token(CHAIN_ID, '0x6B175474E89094C44Da98b954EedeAC495271d0F', 18, 'DAI',  'Dai Stablecoin');
const WBTC = new Token(CHAIN_ID, '0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599', 8, 'WBTC', 'Wrapped Bitcoin');

const TOKENS = { WETH, USDC, USDT, DAI, WBTC };

function SwapPage() {
  const [privateKey, setPrivateKey] = useState('');
  const [wallet, setWallet] = useState(null);
  const [fromToken, setFromToken] = useState('WETH');
  const [toToken, setToToken] = useState('USDC');
  const [amount, setAmount] = useState('');
  const [status, setStatus] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const connectWallet = async () => {
    try {
      let key = privateKey.trim();
      if (key.startsWith('0x')) key = key.slice(2);
      if (!key.match(/^[0-9a-fA-F]{64}$/)) {
        setStatus('❌ Invalid private key.');
        return;
      }
      const provider = new ethers.JsonRpcProvider(ALCHEMY_URL);
      const connected = new ethers.Wallet('0x' + key, provider);
      setWallet(connected);
      setStatus('✅ Wallet connected: ' + connected.address);
    } catch (err) {
      setStatus('❌ ' + err.message);
    }
  };

  const executeSwap = async () => {
    if (!wallet) { setStatus('❌ Connect your wallet first.'); return; }
    if (!amount || isNaN(amount)) { setStatus('❌ Enter a valid amount.'); return; }
    if (fromToken === toToken) { setStatus('❌ Select different tokens.'); return; }

    try {
      setIsLoading(true);
      setStatus('⏳ Getting best route...');

      const provider = new ethers.JsonRpcProvider(ALCHEMY_URL);
      const router = new AlphaRouter({ chainId: CHAIN_ID, provider });

      const inputToken = TOKENS[fromToken];
      const outputToken = TOKENS[toToken];

      const decimals = inputToken.decimals;
      const parsedAmount = CurrencyAmount.fromRawAmount(
        inputToken,
        JSBI.BigInt(ethers.parseUnits(amount, decimals).toString())
      );

      const route = await router.route(
        parsedAmount,
        outputToken,
        TradeType.EXACT_INPUT,
        {
          type: SwapType.SWAP_ROUTER_02,
          recipient: wallet.address,
          slippageTolerance: new Percent(50, 10000), // 0.5%
          deadline: Math.floor(Date.now() / 1000) + 60 * 20,
        }
      );

      if (!route) {
        setStatus('❌ No route found for this swap.');
        setIsLoading(false);
        return;
      }

      setStatus('⏳ Sending transaction...');

      const tx = {
        data: route.methodParameters.calldata,
        to: route.methodParameters.to,
        value: BigInt(route.methodParameters.value),
        from: wallet.address,
        gasLimit: 300000,
      };

      const txResponse = await wallet.sendTransaction(tx);
      setStatus('⏳ Waiting for confirmation...');
      await txResponse.wait();

      setStatus(`✅ Swapped ${amount} ${fromToken} → ${toToken}! Tx: ${txResponse.hash}`);
    } catch (err) {
      console.error(err);
      setStatus('❌ Swap failed: ' + (err.reason || err.message));
    } finally {
      setIsLoading(false);
    }
  };

  const selectStyle = {
    width: '100%',
    padding: '10px',
    fontSize: '16px',
    borderRadius: '8px',
    border: '1px solid #ccc',
    marginBottom: '1rem',
  };

  return (
    <div style={{
      padding: '2rem',
      fontFamily: 'Arial, sans-serif',
      maxWidth: '500px',
      margin: '0 auto',
      background: '#fff9f9',
      borderRadius: '16px',
      boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
    }}>
      <h1 style={{ textAlign: 'center' }}>🐶 Puppy Swap</h1>
      <p style={{ textAlign: 'center', fontSize: '0.85rem', color: '#999' }}>
        Powered by Uniswap · 1% fee supports Puppy Wallet
      </p>

      <input
        type="text"
        placeholder="Enter your private key to swap"
        value={privateKey}
        onChange={(e) => setPrivateKey(e.target.value)}
        autoComplete="off"
        style={{
          width: '100%',
          padding: '12px',
          fontSize: '16px',
          border: '2px solid #ccc',
          borderRadius: '8px',
          marginBottom: '1rem'
        }}
      />

      <button
        onClick={connectWallet}
        style={{
          width: '100%',
          padding: '12px',
          fontSize: '16px',
          backgroundColor: '#ffb6b6',
          border: 'none',
          borderRadius: '8px',
          cursor: 'pointer',
          fontWeight: 'bold',
          marginBottom: '1.5rem'
        }}
      >
        🔐 Connect Wallet
      </button>

      <label>From</label>
      <select value={fromToken} onChange={(e) => setFromToken(e.target.value)} style={selectStyle}>
        {Object.keys(TOKENS).map(t => <option key={t} value={t}>{t}</option>)}
      </select>

      <label>To</label>
      <select value={toToken} onChange={(e) => setToToken(e.target.value)} style={selectStyle}>
        {Object.keys(TOKENS).map(t => <option key={t} value={t}>{t}</option>)}
      </select>

      <input
        type="text"
        placeholder={`Amount in ${fromToken}`}
        value={amount}
        onChange={(e) => setAmount(e.target.value)}
        style={{
          width: '100%',
          padding: '12px',
          fontSize: '16px',
          border: '2px solid #ccc',
          borderRadius: '8px',
          marginBottom: '1rem'
        }}
      />

      <button
        onClick={executeSwap}
        disabled={isLoading}
        style={{
          width: '100%',
          padding: '12px',
          fontSize: '16px',
          backgroundColor: '#90ee90',
          border: 'none',
          borderRadius: '8px',
          cursor: 'pointer',
          fontWeight: 'bold',
          marginBottom: '1rem'
        }}
      >
        {isLoading ? '⏳ Swapping...' : '🔄 Swap'}
      </button>

      {status && (
        <p style={{ textAlign: 'center', fontSize: '0.9rem', color: '#444', wordBreak: 'break-all' }}>
          {status}
        </p>
      )}

      <p style={{ marginTop: '2rem', fontSize: '0.75rem', color: '#999', textAlign: 'center' }}>
        ⚠️ Your private key is never stored or transmitted. Swaps execute directly on-chain via Uniswap v3.
      </p>
    </div>
  );
}

export default SwapPage;
